48	#define HXT_DELAY_EXP_VAL 1000
49	static void LRC_init(void)
50	{
51	    HAL_PMU_RC10Kconfig();
52	
53	    HAL_RC_CAL_update_reference_cycle_on_48M(LXT_LP_CYCLE);
54	    uint32_t ref_cnt = HAL_RC_CAL_get_reference_cycle_on_48M();
55	    uint32_t cycle_t = (uint32_t)ref_cnt / (48 * LXT_LP_CYCLE);
