414	    HAL_LCDC_LayerSetData(hlcdc, HAL_LCDC_LAYER_DEFAULT, (uint8_t *)RGBCode, Xpos0, Ypos0, Xpos1, Ypos1);
415	
416	    /* Keep transfer interrupt-driven so upper layer timeout can recover
417	     * from unexpected LCDC/TE conditions.
418	     */
419	
420	    HAL_LCDC_SendLayerData2Reg_IT(hlcdc, ((0x32 << 24) | (REG_WRITE_RAM << 8)), 4);
421	
422	}
423	
424	
425	/**
426	  * @brief  Writes  to the selected LCD register.
427	  * @param  LCD_Reg: address of the selected register.
428	  * @retval None
429	  */
430	static void LCD_WriteReg(LCDC_HandleTypeDef *hlcdc, uint16_t LCD_Reg, uint8_t *Parameters, uint32_t NbParameters)
431	{
432	    uint32_t cmd;
433	    HAL_StatusTypeDef status;
434	
435	    if ((REG_WRITE_RAM == LCD_Reg) || (REG_CONTINUE_WRITE_RAM == LCD_Reg))
436	    {
437	        cmd = (0x32 << 24) | (LCD_Reg << 8);
438	    }
439	    else
440	    {
441	        cmd = (0x02 << 24) | (LCD_Reg << 8);
442	    }
443	
444	    status = HAL_LCDC_WriteU32Reg(hlcdc, cmd, Parameters, NbParameters);
445	
446	    if (status != HAL_OK)
447	    {
448	        lcdwarn("[co5300] WriteReg failed reg=0x%02x len=%lu st=%d",
449	                LCD_Reg, (unsigned long)NbParameters, status);
450	    }
451	
452	}
453	
454	
455	
456	/**
457	  * @brief  Reads the selected LCD Register.
458	  * @param  RegValue: Address of the register to read
459	  * @param  ReadSize: Number of bytes to read
460	  * @retval LCD Register Value.
461	  */
462	static uint32_t LCD_ReadData(LCDC_HandleTypeDef *hlcdc, uint16_t RegValue, uint8_t ReadSize)
463	{
464	    uint32_t rd_data = 0;
465	
466	    LCD_ReadMode(hlcdc, true);
467	
468	    HAL_LCDC_ReadU32Reg(hlcdc, ((0x03 << 24) | (RegValue << 8)), (uint8_t *)&rd_data, ReadSize);
469	
470	
471	    LCD_ReadMode(hlcdc, false);
472	
473	    return rd_data;
474	}
475	
476	
477	
478	static uint32_t LCD_ReadPixel(LCDC_HandleTypeDef *hlcdc, uint16_t Xpos, uint16_t Ypos)
479	{
480	    uint8_t  r, g, b;
481	    uint32_t ret_v, read_value;
482	    DEBUG_PRINTF("CO5300_ReadPixel[%d,%d]\n", Xpos, Ypos);
483	
484	    LCD_SetRegion(hlcdc, Xpos, Ypos, Xpos, Ypos);
485	
486	    read_value = LCD_ReadData(hlcdc, REG_READ_RAM, 4);
487	    DEBUG_PRINTF("result: [%x]\n", read_value);
488	
489	    b = (read_value >> 0) & 0xFF;
490	    g = (read_value >> 8) & 0xFF;
491	    r = (read_value >> 16) & 0xFF;
492	
493	    DEBUG_PRINTF("r=%d, g=%d, b=%d \n", r, g, b);
494	
495	    switch (lcdc_int_cfg.color_mode)
496	    {
497	    case LCDC_PIXEL_FORMAT_RGB565:
498	        ret_v = (uint32_t)(((r << 11) & 0xF800) | ((g << 5) & 0x7E0) | ((b >> 3) & 0X1F));
499	        break;
500	
501	    /*
502	       (8bit R + 3bit dummy + 8bit G + 3bit dummy + 8bit B)
503	
504	    */
505	    case LCDC_PIXEL_FORMAT_RGB888:
506	        ret_v = (uint32_t)(((r << 16) & 0xFF0000) | ((g << 8) & 0xFF00) | ((b) & 0XFF));
507	        break;
508	
509	    default:
510	        DEBUGASSERT(0);
511	        break;
512	    }
513	
514	    return ret_v;
515	}
516	
517	
518	static void LCD_SetColorMode(LCDC_HandleTypeDef *hlcdc, uint16_t color_mode)
519	{
520	    uint8_t   parameter[2];
521	
522	    switch (color_mode)
523	    {
524	    case RTGRAPHIC_PIXEL_FORMAT_RGB565:
525	        /* Color mode 16bits/pixel */
526	        parameter[0] = 0xD5;
527	        lcdc_int_cfg.color_mode = LCDC_PIXEL_FORMAT_RGB565;
528	        break;
529	
530	    case RTGRAPHIC_PIXEL_FORMAT_RGB888:
531	        parameter[0] = 0xF7;
532	        lcdc_int_cfg.color_mode = LCDC_PIXEL_FORMAT_RGB888;
533	        break;
534	
535	    default:
536	        return; //unsupport
537	        break;
538	    }
539	
540	    LCD_WriteReg(hlcdc, REG_COLOR_MODE, parameter, 1);
541	    HAL_LCDC_SetOutFormat(hlcdc, lcdc_int_cfg.color_mode);
542	}
543	
544	static void  LCD_SetBrightness(LCDC_HandleTypeDef *hlcdc, uint8_t br)
545	{
546	    uint8_t bright = (uint8_t)((int)REG_BRIGHTNESS_MAX * br / 100);
547	    LCD_WriteReg(hlcdc, REG_WBRIGHT, &bright, 1);
548	}
549	
550	/**
551	  * @brief  Enable the Display idle mode.
552	  * @param  None
553	  * @retval None
554	  */
555	static void LCD_IdleModeOn(LCDC_HandleTypeDef *hlcdc)
556	{
557	    uint8_t   parameter[14];
558	
559	    parameter[0] = 0x00;
560	    LCD_WriteReg(hlcdc, 0xFE, parameter, 1);
561	
562	    /* Idle mode On */
563	    LCD_WriteReg(hlcdc, REG_IDLE_MODE_ON, NULL, 0);
564	}
565	
566	/**
567	  * @brief  Disables the Display idle mode.
568	  * @param  None
569	  * @retval None
570	  */
571	static void LCD_IdleModeOff(LCDC_HandleTypeDef *hlcdc)
572	{
573	    uint8_t   parameter[14];
574	
575	    parameter[0] = 0x00;
576	    LCD_WriteReg(hlcdc, 0xFE, parameter, 1);
577	
578	    /* Idle mode Off */
579	    LCD_WriteReg(hlcdc, REG_IDLE_MODE_OFF, NULL, 0);
580	
581	}
582	
583	
584	static const LCD_DrvOpsDef CO5300_drv =
585	{
586	    LCD_Init,
587	    LCD_ReadID,
588	    LCD_DisplayOn,
589	    LCD_DisplayOff,
590	
591	    LCD_SetRegion,
592	    LCD_WritePixel,
593	    LCD_WriteMultiplePixels,
594	
595	    LCD_ReadPixel,
596	
597	    LCD_SetColorMode,
598	    LCD_SetBrightness,
599	    LCD_IdleModeOn,
600	    LCD_IdleModeOff,
601	
602	};
603	
604	LCD_DRIVER_EXPORT(co5300, LCD_ID, &lcdc_int_cfg,
605	                  &CO5300_drv,
606	                  LCD_PIXEL_WIDTH,
607	                  LCD_PIXEL_HEIGHT,
608	                  2);
