/**
 * @file api-interfaces.h
 * @brief VelaWear 系统接口定义
 *
 * 预留所有模块间的API接口，方便后续开发调用
 */

#ifndef __VELAWEAR_API_INTERFACES_H
#define __VELAWEAR_API_INTERFACES_H

#include <stdint.h>
#include <stdbool.h>

#ifdef __cplusplus
extern "C" {
#endif

/* ============================================================
 *  1. 传感器数据接口 (uORB)
 * ============================================================ */

/** 心率数据 */
typedef struct {
    uint64_t timestamp;     /**< 时间戳 (微秒) */
    uint8_t  bpm;           /**< 心率值 (BPM) */
    uint8_t  quality;       /**< 信号质量 (0-100) */
    bool     contact;       /**< 皮肤接触状态 */
} sensor_heart_rate_t;

/** 血氧数据 */
typedef struct {
    uint64_t timestamp;     /**< 时间戳 */
    uint8_t  spo2;          /**< 血氧饱和度 (%) */
    uint8_t  quality;       /**< 信号质量 */
    uint16_t ir_value;      /**< 红外值 */
    uint16_t red_value;     /**< 红光值 */
} sensor_blood_oxygen_t;

/** 加速度计数据 */
typedef struct {
    uint64_t timestamp;     /**< 时间戳 */
    float    x;             /**< X轴加速度 (g) */
    float    y;             /**< Y轴加速度 (g) */
    float    z;             /**< Z轴加速度 (g) */
} sensor_accelerometer_t;

/** 陀螺仪数据 */
typedef struct {
    uint64_t timestamp;     /**< 时间戳 */
    float    x;             /**< X轴角速度 (dps) */
    float    y;             /**< Y轴角速度 (dps) */
    float    z;             /**< Z轴角速度 (dps) */
} sensor_gyroscope_t;

/** 环境光数据 */
typedef struct {
    uint64_t timestamp;     /**< 时间戳 */
    uint32_t lux;           /**< 光照强度 (lux) */
} sensor_ambient_light_t;

/** 电池数据 */
typedef struct {
    uint64_t timestamp;     /**< 时间戳 */
    uint8_t  level;         /**< 电量百分比 (%) */
    uint16_t voltage;       /**< 电压 (mV) */
    bool     charging;      /**< 充电状态 */
    int16_t  current;       /**< 电流 (mA) */
} sensor_battery_t;

/** 温度数据 */
typedef struct {
    uint64_t timestamp;     /**< 时间戳 */
    float    temperature;   /**< 温度 (°C) */
} sensor_temperature_t;

/* uORB 主题定义 */
ORB_DECLARE(heart_rate);
ORB_DECLARE(blood_oxygen);
ORB_DECLARE(accelerometer);
ORB_DECLARE(gyroscope);
ORB_DECLARE(ambient_light);
ORB_DECLARE(battery);
ORB_DECLARE(temperature);

/* ============================================================
 *  2. 健康监测接口
 * ============================================================ */

/** 健康数据聚合 */
typedef struct {
    sensor_heart_rate_t    heart_rate;
    sensor_blood_oxygen_t  blood_oxygen;
    uint32_t               steps;          /**< 步数 */
    float                  distance;       /**< 距离 (km) */
    uint32_t               calories;       /**< 卡路里 (kcal) */
    uint32_t               active_minutes; /**< 活动分钟 */
} health_data_t;

/** 睡眠阶段 */
typedef enum {
    SLEEP_STAGE_AWAKE = 0,
    SLEEP_STAGE_LIGHT,
    SLEEP_STAGE_DEEP,
    SLEEP_STAGE_REM
} sleep_stage_t;

/** 睡眠数据 */
typedef struct {
    uint64_t      start_time;      /**< 开始时间 */
    uint64_t      end_time;        /**< 结束时间 */
    uint32_t      total_minutes;   /**< 总睡眠时长 (分钟) */
    uint32_t      deep_minutes;    /**< 深度睡眠 (分钟) */
    uint32_t      light_minutes;   /**< 浅度睡眠 (分钟) */
    uint32_t      rem_minutes;     /**< REM睡眠 (分钟) */
    uint8_t       quality_score;   /**< 睡眠质量评分 (0-100) */
} sleep_data_t;

/** 压力等级 */
typedef enum {
    STRESS_LEVEL_RELAXED = 0,
    STRESS_LEVEL_NORMAL,
    STRESS_LEVEL_MEDIUM,
    STRESS_LEVEL_HIGH
} stress_level_t;

/** API: 获取当前健康数据 */
int health_get_current_data(health_data_t *data);

/** API: 获取今日步数 */
uint32_t health_get_steps(void);

/** API: 获取睡眠数据 */
int health_get_sleep_data(sleep_data_t *data);

/** API: 获取压力等级 */
stress_level_t health_get_stress_level(void);

/* ============================================================
 *  3. 运动模式接口
 * ============================================================ */

/** 运动类型 */
typedef enum {
    SPORT_TYPE_RUNNING = 0,
    SPORT_TYPE_CYCLING,
    SPORT_TYPE_SWIMMING,
    SPORT_TYPE_YOGA,
    SPORT_TYPE_STRENGTH,
    SPORT_TYPE_HIKING,
    SPORT_TYPE_MAX
} sport_type_t;

/** 运动状态 */
typedef enum {
    SPORT_STATE_IDLE = 0,
    SPORT_STATE_PAUSED,
    SPORT_STATE_ACTIVE,
    SPORT_STATE_FINISHED
} sport_state_t;

/** 运动数据 */
typedef struct {
    sport_type_t  type;           /**< 运动类型 */
    sport_state_t state;          /**< 运动状态 */
    uint32_t      duration_sec;   /**< 持续时间 (秒) */
    float         distance_km;    /**< 距离 (km) */
    uint32_t      calories;       /**< 卡路里 */
    uint8_t       avg_heart_rate; /**< 平均心率 */
    uint8_t       max_heart_rate; /**< 最大心率 */
    float         pace;           /**< 配速 (min/km) */
    float         speed;          /**< 速度 (km/h) */
    uint32_t      steps;          /**< 步数 */
} sport_data_t;

/** GPS 数据 */
typedef struct {
    double latitude;    /**< 纬度 */
    double longitude;   /**< 经度 */
    float  altitude;    /**< 海拔 (m) */
    float  accuracy;    /**< 精度 (m) */
} gps_data_t;

/** API: 开始运动 */
int sport_start(sport_type_t type);

/** API: 暂停运动 */
int sport_pause(void);

/** API: 恢复运动 */
int sport_resume(void);

/** API: 停止运动 */
int sport_stop(void);

/** API: 获取运动数据 */
int sport_get_data(sport_data_t *data);

/* ============================================================
 *  4. LVGL UI 接口
 * ============================================================ */

/** 屏幕页面ID */
typedef enum {
    PAGE_WATCHFACE = 0,     /**< 主表盘 */
    PAGE_CARDS,             /**< 卡片流 */
    PAGE_NOTIFICATIONS,     /**< 通知中心 */
    PAGE_APP_LIST,          /**< 应用列表 */
    PAGE_HEART,             /**< 心率详情 */
    PAGE_SPO2,              /**< 血氧详情 */
    PAGE_SPORT,             /**< 运动模式 */
    PAGE_SLEEP,             /**< 睡眠详情 */
    PAGE_STRESS,            /**< 压力详情 */
    PAGE_BREATH,            /**< 呼吸训练 */
    PAGE_WEATHER,           /**< 天气 */
    PAGE_MUSIC,             /**< 音乐 */
    PAGE_TIMER,             /**< 计时器 */
    PAGE_ALARM,             /**< 闹钟 */
    PAGE_COMPASS,           /**< 指南针 */
    PAGE_FLASHLIGHT,        /**< 手电筒 */
    PAGE_FIND_PHONE,        /**< 找手机 */
    PAGE_NFC,               /**< NFC */
    PAGE_CALCULATOR,        /**< 计算器 */
    PAGE_SETTINGS,          /**< 设置 */
    PAGE_MAX
} page_id_t;

/** 页面切换动画 */
typedef enum {
    ANIM_NONE = 0,
    ANIM_MOVE_LEFT,
    ANIM_MOVE_RIGHT,
    ANIM_MOVE_UP,
    ANIM_MOVE_DOWN,
    ANIM_FADE,
    ANIM_SCALE
} page_anim_t;

/** 手势类型 */
typedef enum {
    GESTURE_NONE = 0,
    GESTURE_SWIPE_LEFT,
    GESTURE_SWIPE_RIGHT,
    GESTURE_SWIPE_UP,
    GESTURE_SWIPE_DOWN,
    GESTURE_TAP,
    GESTURE_LONG_PRESS,
    GESTURE_DOUBLE_TAP
} gesture_type_t;

/** 手势回调 */
typedef void (*gesture_cb_t)(gesture_type_t gesture, void *user_data);

/** API: 切换页面 */
int ui_switch_page(page_id_t page, page_anim_t anim);

/** API: 获取当前页面 */
page_id_t ui_get_current_page(void);

/** API: 注册手势回调 */
int ui_register_gesture_cb(gesture_cb_t cb, void *user_data);

/** API: 更新表盘时间 */
void ui_watchface_update_time(void);

/** API: 更新健康指标显示 */
void ui_watchface_update_health(const health_data_t *data);

/** API: 显示通知 */
void ui_notification_show(const char *app, const char *title, const char *content);

/** API: 清除所有通知 */
void ui_notification_clear_all(void);

/* ============================================================
 *  5. 通知管理接口
 * ============================================================ */

/** 通知来源 */
typedef enum {
    NOTIF_SOURCE_PHONE = 0,     /**< 手机转发 */
    NOTIF_SOURCE_APP,           /**< 本地应用 */
    NOTIF_SOURCE_SYSTEM         /**< 系统通知 */
} notif_source_t;

/** 通知数据 */
typedef struct {
    uint32_t      id;           /**< 通知ID */
    notif_source_t source;      /**< 来源 */
    char          app[32];      /**< 应用名 */
    char          title[64];    /**< 标题 */
    char          content[256]; /**< 内容 */
    uint64_t      timestamp;    /**< 时间戳 */
    bool          read;         /**< 已读状态 */
} notification_t;

/** API: 添加通知 */
int notification_add(const notification_t *notif);

/** API: 获取通知列表 */
int notification_get_list(notification_t *list, uint32_t max_count);

/** API: 标记已读 */
int notification_mark_read(uint32_t id);

/** API: 删除通知 */
int notification_delete(uint32_t id);

/** API: 清除所有通知 */
int notification_clear_all(void);

/* ============================================================
 *  6. BLE 通信接口
 * ============================================================ */

/** BLE 连接状态 */
typedef enum {
    BLE_STATE_DISCONNECTED = 0,
    BLE_STATE_CONNECTING,
    BLE_STATE_CONNECTED,
    BLE_STATE_DISCONNECTING
} ble_state_t;

/** BLE 数据类型 */
typedef enum {
    BLE_DATA_HEALTH = 0,       /**< 健康数据 */
    BLE_DATA_SPORT,            /**< 运动数据 */
    BLE_DATA_NOTIFICATION,     /**< 通知 */
    BLE_DATA_WEATHER,          /**< 天气 */
    BLE_DATA_MUSIC,            /**< 音乐控制 */
    BLE_DATA_SETTINGS,         /**< 设置同步 */
    BLE_DATA_OTA               /**< OTA升级 */
} ble_data_type_t;

/** BLE 数据包 */
typedef struct {
    ble_data_type_t type;       /**< 数据类型 */
    uint16_t        length;     /**< 数据长度 */
    uint8_t         data[256];  /**< 数据内容 */
} ble_packet_t;

/** BLE 回调 */
typedef void (*ble_connect_cb_t)(ble_state_t state);
typedef void (*ble_receive_cb_t)(const ble_packet_t *packet);

/** API: 初始化BLE */
int ble_init(void);

/** API: 开始广播 */
int ble_start_advertising(void);

/** API: 停止广播 */
int ble_stop_advertising(void);

/** API: 发送数据 */
int ble_send_data(const ble_packet_t *packet);

/** API: 注册连接回调 */
int ble_register_connect_cb(ble_connect_cb_t cb);

/** API: 注册接收回调 */
int ble_register_receive_cb(ble_receive_cb_t cb);

/** API: 获取连接状态 */
ble_state_t ble_get_state(void);

/* ============================================================
 *  7. 手机APP通信协议
 * ============================================================ */

/** 协议命令 */
typedef enum {
    CMD_PHONE_SYNC_TIME = 0x01,      /**< 同步时间 */
    CMD_PHONE_SYNC_WEATHER = 0x02,   /**< 同步天气 */
    CMD_PHONE_SYNC_CONTACTS = 0x03,  /**< 同步联系人 */
    CMD_PHONE_NOTIFICATION = 0x10,   /**< 推送通知 */
    CMD_PHONE_MUSIC_CTRL = 0x20,     /**< 音乐控制 */
    CMD_PHONE_FIND_WATCH = 0x30,     /**< 找手表 */
    CMD_PHONE_OTA_START = 0x40,      /**< 开始OTA */
    CMD_PHONE_OTA_DATA = 0x41,       /**< OTA数据 */
    CMD_PHONE_OTA_END = 0x42,        /**< 结束OTA */
} phone_cmd_t;

/** 手机通知数据 */
typedef struct {
    char app_name[32];      /**< 应用名 */
    char title[64];         /**< 标题 */
    char content[256];      /**< 内容 */
    uint64_t timestamp;     /**< 时间戳 */
} phone_notification_t;

/** 天气数据 */
typedef struct {
    int8_t   temperature;   /**< 温度 */
    uint8_t  humidity;      /**< 湿度 */
    uint16_t wind_speed;    /**< 风速 */
    uint8_t  condition;     /**< 天气状况 */
    uint8_t  aqi;           /**< 空气质量 */
    char     city[32];      /**< 城市 */
} weather_data_t;

/** 音乐控制命令 */
typedef enum {
    MUSIC_CMD_PLAY = 0,
    MUSIC_CMD_PAUSE,
    MUSIC_CMD_NEXT,
    MUSIC_CMD_PREV,
    MUSIC_CMD_VOLUME_UP,
    MUSIC_CMD_VOLUME_DOWN
} music_cmd_t;

/** 音乐信息 */
typedef struct {
    char title[64];         /**< 歌曲名 */
    char artist[64];        /**< 歌手 */
    char album[64];         /**< 专辑 */
    uint32_t duration;      /**< 时长 (秒) */
    uint32_t position;      /**< 当前位置 (秒) */
    uint8_t  volume;        /**< 音量 */
    bool     playing;       /**< 播放状态 */
} music_info_t;

/* ============================================================
 *  8. 存储接口
 * ============================================================ */

/** 存储类型 */
typedef enum {
    STORAGE_TYPE_CONFIG = 0,    /**< 配置数据 */
    STORAGE_TYPE_HEALTH,        /**< 健康历史 */
    STORAGE_TYPE_SPORT,         /**< 运动记录 */
    STORAGE_TYPE_NOTIFICATION,  /**< 通知存储 */
    STORAGE_TYPE_WATCHFACE,     /**< 表盘设置 */
    STORAGE_TYPE_USER           /**< 用户数据 */
} storage_type_t;

/** API: 保存数据 */
int storage_save(storage_type_t type, const char *key, const void *data, uint32_t size);

/** API: 读取数据 */
int storage_load(storage_type_t type, const char *key, void *data, uint32_t size);

/** API: 删除数据 */
int storage_delete(storage_type_t type, const char *key);

/** API: 检查是否存在 */
bool storage_exists(storage_type_t type, const char *key);

/** API: 清空指定类型数据 */
int storage_clear(storage_type_t type);

/* ============================================================
 *  9. 系统服务接口
 * ============================================================ */

/** 系统状态 */
typedef struct {
    uint8_t   battery_level;    /**< 电量 */
    bool      charging;         /**< 充电中 */
    bool      bluetooth_on;     /**< 蓝牙开关 */
    bool      dnd_mode;         /**< 勿扰模式 */
    uint8_t   brightness;       /**< 亮度 */
    bool      wrist_wake;       /**< 抬腕唤醒 */
    uint32_t  uptime_sec;       /**< 运行时间 */
} system_status_t;

/** 低功耗模式 */
typedef enum {
    POWER_MODE_NORMAL = 0,      /**< 正常模式 */
    POWER_MODE_LOW_POWER,       /**< 低功耗 */
    POWER_MODE_ULTRA_LOW,       /**< 超低功耗 */
    POWER_MODE_SLEEP            /**< 睡眠模式 */
} power_mode_t;

/** API: 获取系统状态 */
int system_get_status(system_status_t *status);

/** API: 设置亮度 */
int system_set_brightness(uint8_t level);

/** API: 设置功耗模式 */
int system_set_power_mode(power_mode_t mode);

/** API: 重启系统 */
void system_reboot(void);

/** API: 恢复出厂设置 */
void system_factory_reset(void);

/* ============================================================
 *  10. 闹钟/提醒接口
 * ============================================================ */

/** 闹钟重复模式 */
typedef enum {
    ALARM_ONCE = 0,         /**< 单次 */
    ALARM_DAILY,            /**< 每天 */
    ALARM_WEEKDAYS,         /**< 工作日 */
    ALARM_WEEKENDS,         /**< 周末 */
    ALARM_CUSTOM            /**< 自定义 */
} alarm_repeat_t;

/** 闹钟数据 */
typedef struct {
    uint32_t     id;            /**< 闹钟ID */
    uint8_t      hour;          /**< 小时 */
    uint8_t      minute;        /**< 分钟 */
    alarm_repeat_t repeat;      /**< 重复模式 */
    uint8_t      weekdays;      /**< 星期掩码 (bit0=周日) */
    bool         enabled;       /**< 启用状态 */
    char         label[32];     /**< 标签 */
    uint8_t      snooze_min;    /**< 贪睡时间 */
} alarm_data_t;

/** API: 添加闹钟 */
int alarm_add(const alarm_data_t *alarm);

/** API: 删除闹钟 */
int alarm_delete(uint32_t id);

/** API: 修改闹钟 */
int alarm_update(const alarm_data_t *alarm);

/** API: 获取闹钟列表 */
int alarm_get_list(alarm_data_t *list, uint32_t max_count);

/** API: 贪睡 */
int alarm_snooze(uint32_t id);

/** API: 关闭闹钟 */
int alarm_dismiss(uint32_t id);

/* ============================================================
 *  11. NFC 接口 (预留)
 * ============================================================ */

/** NFC 模式 */
typedef enum {
    NFC_MODE_CARD = 0,      /**< 模拟门禁卡 */
    NFC_MODE_PAYMENT,       /**< 模拟支付 */
    NFC_MODE_READER         /**< 读卡模式 */
} nfc_mode_t;

/** API: 初始化NFC */
int nfc_init(void);

/** API: 开启NFC */
int nfc_enable(nfc_mode_t mode);

/** API: 关闭NFC */
int nfc_disable(void);

/* ============================================================
 *  12. 表盘定制接口
 * ============================================================ */

/** 表盘样式 */
typedef enum {
    WATCHFACE_ANALOG = 0,   /**< 指针式 */
    WATCHFACE_DIGITAL,      /**< 数字式 */
    WATCHFACE_MIXED,        /**< 混合式 */
    WATCHFACE_CUSTOM        /**< 自定义 */
} watchface_style_t;

/** 复杂功能类型 */
typedef enum {
    COMPLICATION_HEART = 0, /**< 心率 */
    COMPLICATION_STEPS,     /**< 步数 */
    COMPLICATION_SPO2,      /**< 血氧 */
    COMPLICATION_CALORIES,  /**< 卡路里 */
    COMPLICATION_BATTERY,   /**< 电量 */
    COMPLICATION_WEATHER,   /**< 天气 */
    COMPLICATION_DATE,      /**< 日期 */
    COMPLICATION_MAX
} complication_type_t;

/** 表盘配置 */
typedef struct {
    watchface_style_t style;                    /**< 样式 */
    complication_type_t complications[6];       /**< 复杂功能 */
    uint8_t   complication_count;               /**< 数量 */
    uint32_t  color_theme;                      /**< 颜色主题 */
    bool      show_seconds;                     /**< 显示秒针 */
} watchface_config_t;

/** API: 设置表盘 */
int watchface_set_config(const watchface_config_t *config);

/** API: 获取表盘配置 */
int watchface_get_config(watchface_config_t *config);

/* ============================================================
 *  13. 呼吸训练接口
 * ============================================================ */

/** 呼吸模式 */
typedef enum {
    BREATH_MODE_RELAX = 0,      /**< 放松模式 */
    BREATH_MODE_FOCUS,          /**< 专注模式 */
    BREATH_MODE_ENERGY,         /**< 活力模式 */
    BREATH_MODE_CUSTOM          /**< 自定义 */
} breath_mode_t;

/** 呼吸数据 */
typedef struct {
    breath_mode_t mode;         /**< 模式 */
    uint32_t duration_sec;      /**< 持续时间 */
    uint8_t  breaths_per_min;   /**< 每分钟呼吸次数 */
    uint8_t  heart_rate_start;  /**< 开始心率 */
    uint8_t  heart_rate_end;    /**< 结束心率 */
} breath_session_t;

/** API: 开始呼吸训练 */
int breath_start(breath_mode_t mode, uint32_t duration_sec);

/** API: 停止呼吸训练 */
int breath_stop(void);

/** API: 获取呼吸训练数据 */
