 * ============================================================ */

/** OTA 状态 */
typedef enum {
    OTA_STATE_IDLE = 0,
    OTA_STATE_DOWNLOADING,
    OTA_STATE_VERIFYING,
    OTA_STATE_INSTALLING,
    OTA_STATE_DONE,
    OTA_STATE_ERROR
} ota_state_t;

/** OTA 回调 */
typedef void (*ota_progress_cb_t)(ota_state_t state, uint8_t progress);

/** API: 开始OTA */
