// ============================================================
//  时间更新
// ============================================================
function updateTime() {
  const now = new Date();
  const h = String(now.getHours()).padStart(2, '0');
  const m = String(now.getMinutes()).padStart(2, '0');
  document.getElementById('timeDisplay').textContent = `${h}:${m}`;

  const month = now.getMonth() + 1;
  const date = now.getDate();
  const days = ['日', '一', '二', '三', '四', '五', '六'];
  const day = days[now.getDay()];
  document.getElementById('dateDisplay').textContent = `${month}月${date}日 周${day}`;
}

// ============================================================
//  呼吸训练
// ============================================================
let breathInterval = null;
function startBreath(mode) {
  const circle = document.getElementById('breathCircle');
  const text = document.getElementById('breathText');
  const instruction = document.getElementById('breathInstruction');

  if (breathInterval) clearInterval(breathInterval);

  let cycles = {relax: {in:4, hold:7, out:8}, focus: {in:5, hold:5, out:5}, energy: {in:3, hold:3, out:3}};
  let c = cycles[mode];
  let phase = 0; // 0=吸气, 1=屏息, 2=呼气

  function breathCycle() {
    if (phase === 0) {
      text.textContent = '吸气';
      instruction.textContent = `${c.in}秒`;
      circle.style.transform = 'scale(1.3)';
      circle.style.transition = `transform ${c.in}s ease-in-out`;
      setTimeout(() => { phase = 1; }, c.in * 1000);
    } else if (phase === 1) {
      text.textContent = '屏息';
      instruction.textContent = `${c.hold}秒`;
      setTimeout(() => { phase = 2; }, c.hold * 1000);
    } else {
      text.textContent = '呼气';
      instruction.textContent = `${c.out}秒`;
      circle.style.transform = 'scale(1)';
      circle.style.transition = `transform ${c.out}s ease-in-out`;
      setTimeout(() => { phase = 0; }, c.out * 1000);
    }
  }

  breathCycle();
  breathInterval = setInterval(breathCycle, (c.in + c.hold + c.out) * 1000);
}

// ============================================================
//  指南针
// ============================================================
let compassDegree = 127;
function updateCompass() {
  compassDegree = (compassDegree + 0.5) % 360;
  const needle = document.getElementById('compassNeedle');
  const degree = document.getElementById('compassDegree');
  const direction = document.getElementById('compassDirection');

  needle.style.transform = `translate(-50%, -100%) rotate(${compassDegree}deg)`;
  degree.textContent = `${Math.round(compassDegree)}°`;

  const dirs = ['北', '东北', '东', '东南', '南', '西南', '西', '西北'];
  const idx = Math.round(compassDegree / 45) % 8;
  direction.textContent = dirs[idx];
}

// ============================================================
//  手电筒
// ============================================================
let flashlightOn = false;
function toggleFlashlight() {
  flashlightOn = !flashlightOn;
  const btn = document.getElementById('flashlightBtn');
  const status = document.getElementById('flashlightStatus');

  if (flashlightOn) {
    btn.style.background = 'rgba(255,255,200,0.9)';
    btn.style.boxShadow = '0 0 50px rgba(255,255,200,0.5)';
    status.textContent = '点击关闭手电筒';
  } else {
    btn.style.background = 'rgba(255,255,255,0.1)';
    btn.style.boxShadow = 'none';
    status.textContent = '点击开启手电筒';
  }
}

// ============================================================
//  找手机
// ============================================================
let findPhoneActive = false;
function toggleFindPhone() {
  findPhoneActive = !findPhoneActive;
  const btn = document.getElementById('findPhoneBtn');
  const status = document.getElementById('findPhoneStatus');

  if (findPhoneActive) {
    btn.style.background = 'rgba(162,155,254,0.5)';
    btn.style.animation = 'pulse 1s infinite';
    status.textContent = '手机正在响铃...';
  } else {
    btn.style.background = 'rgba(162,155,254,0.2)';
    btn.style.animation = 'none';
    status.textContent = '点击让手机响铃';
  }
}

// ============================================================
//  计算器
// ============================================================
let calcExpr = '';
let calcResultShown = false;

function calcInput(val) {
  if (calcResultShown) {
    calcExpr = '';
    calcResultShown = false;
  }
  calcExpr += val;
  document.getElementById('calcExpression').textContent = calcExpr;
}

function calcClear() {
  calcExpr = '';
  document.getElementById('calcExpression').textContent = '';
  document.getElementById('calcDisplay').textContent = '0';
}

function calcResult() {
  try {
    const result = eval(calcExpr);
    document.getElementById('calcDisplay').textContent = result;
    document.getElementById('calcExpression').textContent = calcExpr + '=';
    calcExpr = String(result);
    calcResultShown = true;
  } catch (e) {
    document.getElementById('calcDisplay').textContent = '错误';
  }
}

// ============================================================
//  日历
// ============================================================
function initCalendar() {
  const now = new Date();
  const year = now.getFullYear();
  const month = now.getMonth();
  const today = now.getDate();

  const firstDay = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();

  const container = document.getElementById('calendarDays');
  let html = '';

  // 空白天数
  for (let i = 0; i < firstDay; i++) {
    html += '<div style="padding:8px 0"></div>';
  }

  // 日期
  for (let d = 1; d <= daysInMonth; d++) {
    const isToday = d === today;
    const style = isToday
      ? 'padding:8px 0;background:#6b8cff;border-radius:50%;color:white'
      : 'padding:8px 0';
    html += `<div style="${style}">${d}</div>`;
  }

  container.innerHTML = html;
}

// ============================================================
//  初始化
// ============================================================
function init() {
  updateTime();
  setInterval(updateTime, 1000);
  setInterval(updateCompass, 100);
  initHeartChart();
  initCalendar();
  showWatchface();
}

init();

