/**
 * @file main.c
 * @brief VelaWear 主程序入口
 *
 * 2026 OpenVela AI 硬件开发者大赛 - team329
 * 立创黄山派开发板
 */

#include <stdio.h>
#include <stdlib.h>
#include "velawear_config.h"

/* 头文件声明 */
void system_init(void);
void display_init(void);
void touch_init(void);
void sensors_init(void);
void ui_init(void);
void ble_init(void);
void ai_agent_init(void);
void health_init(void);
void sports_init(void);

/**
 * @brief 主函数
 */
int main(void)
{
