/**
 * @file sensor_driver.h
 * @brief 传感器驱动接口
 *
 * 支持心率、血氧、加速度计、陀螺仪等传感器
 * 2026 OpenVela AI 硬件开发者大赛 - team329
 */

#ifndef SENSOR_DRIVER_H
#define SENSOR_DRIVER_H

#include <stdint.h>
#include <stdbool.h>

/* 传感器类型 */
typedef enum {
    SENSOR_TYPE_HEART_RATE = 0,
    SENSOR_TYPE_BLOOD_OXYGEN,
    SENSOR_TYPE_ACCELEROMETER,
    SENSOR_TYPE_GYROSCOPE,
    SENSOR_TYPE_MAGNETOMETER,
    SENSOR_TYPE_TEMPERATURE,
    SENSOR_TYPE_HUMIDITY,
    SENSOR_TYPE_LIGHT,
    SENSOR_TYPE_MAX
} sensor_type_t;

/* 传感器数据 */
typedef struct {
    sensor_type_t type;
    union {
        struct {
            uint32_t bpm;           /* 心率 (bpm) */
            uint8_t quality;        /* 信号质量 (0-100) */
            bool is_valid;          /* 数据是否有效 */
        } heart_rate;

        struct {
            uint8_t spo2;           /* 血氧饱和度 (%) */
            uint8_t quality;        /* 信号质量 (0-100) */
            bool is_valid;          /* 数据是否有效 */
        } blood_oxygen;

        struct {
            float x;                /* X 轴加速度 (m/s²) */
            float y;                /* Y 轴加速度 (m/s²) */
            float z;                /* Z 轴加速度 (m/s²) */
        } accelerometer;

        struct {
            float x;                /* X 轴角速度 (°/s) */
            float y;                /* Y 轴角速度 (°/s) */
            float z;                /* Z 轴角速度 (°/s) */
        } gyroscope;

        struct {
            float temperature;      /* 温度 (°C) */
            float humidity;         /* 湿度 (%) */
        } environment;

        struct {
            uint32_t lux;           /* 光照强度 (lux) */
        } light;
    };
    uint32_t timestamp;             /* 时间戳 */
} sensor_data_t;

/* 传感器配置 */
typedef struct {
    uint8_t sample_rate;            /* 采样率 (Hz) */
    uint8_t range;                  /* 量程 */
    uint8_t resolution;             /* 分辨率 */
    bool enable;                    /* 是否启用 */
} sensor_config_t;

/* 传感器句柄 */
typedef struct {
    sensor_type_t type;
    sensor_config_t config;
    sensor_data_t data;
    bool initialized;
} sensor_handle_t;

/* 传感器回调函数类型 */
typedef void (*sensor_callback_t)(sensor_data_t *data);

/**
 * @brief 初始化传感器
 * @param type 传感器类型
 * @return 传感器句柄，NULL 表示失败
 */
sensor_handle_t* sensor_init(sensor_type_t type);

/**
 * @brief 关闭传感器
 * @param handle 传感器句柄
 * @return 0 成功，负值失败
 */
int sensor_deinit(sensor_handle_t *handle);

/**
 * @brief 读取传感器数据
 * @param handle 传感器句柄
 * @param data 数据指针
 * @return 0 成功，负值失败
 */
int sensor_read(sensor_handle_t *handle, sensor_data_t *data);

/**
 * @brief 设置传感器采样率
 * @param handle 传感器句柄
 * @param rate 采样率 (Hz)
 * @return 0 成功，负值失败
 */
int sensor_set_sample_rate(sensor_handle_t *handle, uint8_t rate);

/**
 * @brief 注册传感器回调
 * @param handle 传感器句柄
 * @param callback 回调函数
 */
void sensor_register_callback(sensor_handle_t *handle, sensor_callback_t callback);

/**
 * @brief 启用传感器
 * @param handle 传感器句柄
 * @return 0 成功，负值失败
 */
int sensor_enable(sensor_handle_t *handle);

/**
 * @brief 禁用传感器
 * @param handle 传感器句柄
 * @return 0 成功，负值失败
 */
int sensor_disable(sensor_handle_t *handle);

/**
 * @brief 获取传感器信息
 * @param type 传感器类型
 * @param name 传感器名称
 * @param description 描述
 */
void sensor_get_info(sensor_type_t type, const char **name, const char **description);

#endif /* SENSOR_DRIVER_H */

