/**
 * @file health_manager.h
 * @brief 健康监测管理器接口
 *
 * 心率、血氧、睡眠、压力监测
 * 2026 OpenVela AI 硬件开发者大赛 - team329
 */

#ifndef HEALTH_MANAGER_H
#define HEALTH_MANAGER_H

#include <stdint.h>
#include <stdbool.h>

/* 健康数据类型 */
typedef enum {
    HEALTH_TYPE_HEART_RATE = 0,
    HEALTH_TYPE_BLOOD_OXYGEN,
    HEALTH_TYPE_SLEEP,
    HEALTH_TYPE_STRESS,
    HEALTH_TYPE_TEMPERATURE,
    HEALTH_TYPE_MAX
} health_type_t;

/* 心率数据 */
typedef struct {
    uint32_t bpm;               /* 心率 (bpm) */
    uint8_t quality;            /* 信号质量 (0-100) */
    bool is_measuring;          /* 是否正在测量 */
    uint32_t last_update;       /* 最后更新时间 */
} heart_rate_data_t;

/* 血氧数据 */
typedef struct {
    uint8_t spo2;               /* 血氧饱和度 (%) */
    uint8_t quality;            /* 信号质量 (0-100) */
    bool is_measuring;          /* 是否正在测量 */
    uint32_t last_update;       /* 最后更新时间 */
} blood_oxygen_data_t;

/* 睡眠阶段 */
typedef enum {
    SLEEP_STAGE_AWAKE = 0,
    SLEEP_STAGE_LIGHT,
    SLEEP_STAGE_DEEP,
    SLEEP_STAGE_REM,
    SLEEP_STAGE_MAX
} sleep_stage_t;

/* 睡眠数据 */
typedef struct {
    uint32_t duration_min;      /* 睡眠时长 (分钟) */
    sleep_stage_t quality;      /* 睡眠质量 */
    uint32_t deep_sleep_min;    /* 深睡时长 */
    uint32_t light_sleep_min;   /* 浅睡时长 */
    uint32_t rem_sleep_min;     /* REM 时长 */
    uint32_t awake_min;         /* 清醒时长 */
    uint32_t start_time;        /* 开始时间 */
    uint32_t end_time;          /* 结束时间 */
} sleep_data_t;

/* 压力数据 */
typedef struct {
    uint8_t level;              /* 压力等级 (0-100) */
    const char *label;          /* 压力标签 (低/中/高/极高) */
    bool is_measuring;          /* 是否正在测量 */
    uint32_t last_update;       /* 最后更新时间 */
} stress_data_t;

/* 健康数据联合体 */
typedef union {
    heart_rate_data_t heart_rate;
    blood_oxygen_data_t blood_oxygen;
    sleep_data_t sleep;
    stress_data_t stress;
} health_data_union_t;

/* 健康数据 */
typedef struct {
    health_type_t type;
    health_data_union_t data;
    uint32_t timestamp;
} health_data_t;

/* 健康配置 */
typedef struct {
    bool enable_heart_rate;     /* 启用心率监测 */
    bool enable_blood_oxygen;   /* 启用血氧监测 */
    bool enable_sleep;          /* 启用睡眠监测 */
    bool enable_stress;         /* 启用压力监测 */
    uint16_t hr_interval;       /* 心率测量间隔 (秒) */
    uint16_t spo2_interval;     /* 血氧测量间隔 (秒) */
} health_config_t;

/* 健康句柄 */
typedef struct {
    health_config_t config;
    heart_rate_data_t heart_rate;
    blood_oxygen_data_t blood_oxygen;
    sleep_data_t sleep;
    stress_data_t stress;
    bool initialized;
} health_handle_t;

/* 健康回调函数类型 */
