/**
 * @file ai_agent.h
 * @brief AI Agent 框架接口
 *
 * LLM 后端、Skill 系统、Tool 系统
 * 2026 OpenVela AI 硬件开发者大赛 - team329
 */

#ifndef AI_AGENT_H
#define AI_AGENT_H

#include <stdint.h>
#include <stdbool.h>

/* LLM 后端类型 */
typedef enum {
    LLM_BACKEND_LOCAL = 0,      /* MiMo-Edge-3B */
    LLM_BACKEND_CLOUD,          /* DeepSeek */
    LLM_BACKEND_HYBRID,         /* 混合模式 */
    LLM_BACKEND_MAX
} llm_backend_t;

/* Agent 状态 */
typedef enum {
    AGENT_STATE_IDLE = 0,
    AGENT_STATE_THINKING,
    AGENT_STATE_EXECUTING,
    AGENT_STATE_SPEAKING,
    AGENT_STATE_ERROR
} agent_state_t;

/* 消息角色 */
typedef enum {
    MESSAGE_ROLE_USER = 0,
    MESSAGE_ROLE_ASSISTANT,
    MESSAGE_ROLE_SYSTEM
} message_role_t;

/* 消息 */
typedef struct {
    message_role_t role;
    char content[512];
    uint32_t timestamp;
} agent_message_t;

/* Agent 响应 */
typedef struct {
    char content[512];          /* 响应内容 */
    char action[64];            /* 执行的动作 */
    char parameters[256];       /* 动作参数 */
    bool has_action;            /* 是否有动作 */
    uint32_t timestamp;
} agent_response_t;

/* Skill 接口 */
typedef struct {
    const char *name;           /* Skill 名称 */
    const char *description;    /* Skill 描述 */
    bool (*should_trigger)(const char *input);  /* 触发条件 */
    agent_response_t (*execute)(const char *input);  /* 执行函数 */
} ai_skill_t;

/* Tool 接口 */
typedef struct {
    const char *name;           /* Tool 名称 */
    const char *description;    /* Tool 描述 */
    const char *parameters;     /* 参数描述 */
    agent_response_t (*execute)(const char *params);  /* 执行函数 */
} ai_tool_t;

/* Agent 配置 */
typedef struct {
    llm_backend_t backend;      /* LLM 后端 */
    uint8_t max_skills;         /* 最大 Skill 数量 */
    uint8_t max_tools;          /* 最大 Tool 数量 */
    bool enable_proactive;      /* 启用主动触发 */
    uint16_t context_length;    /* 上下文长度 */
} ai_config_t;

/* Agent 句柄 */
typedef struct {
    ai_config_t config;
    agent_state_t state;
    ai_skill_t skills[16];
    ai_tool_t tools[32];
    uint8_t skill_count;
    uint8_t tool_count;
    agent_message_t context[10]; /* 对话上下文 */
    uint8_t context_index;
    bool initialized;
} ai_handle_t;

/**
 * @brief 初始化 AI Agent
 * @param handle Agent 句柄
 * @return 0 成功，负值失败
 */
int ai_init(ai_handle_t *handle);

/**
 * @brief 关闭 AI Agent
 * @param handle Agent 句柄
 * @return 0 成功，负值失败
 */
int ai_deinit(ai_handle_t *handle);

/**
 * @brief 处理用户输入
 * @param handle Agent 句柄
 * @param input 用户输入
 * @param response 响应
 * @return 0 成功，负值失败
 */
int ai_process(ai_handle_t *handle, const char *input, agent_response_t *response);

/**
 * @brief 主动触发
 * @param handle Agent 句柄
 * @param trigger 触发条件
 * @param response 响应
 * @return 0 成功，负值失败
 */
int ai_proactive(ai_handle_t *handle, const char *trigger, agent_response_t *response);

/**
 * @brief 注册 Skill
 * @param handle Agent 句柄
 * @param skill Skill 实例
 * @return 0 成功，负值失败
 */
int ai_register_skill(ai_handle_t *handle, const ai_skill_t *skill);

/**
 * @brief 注册 Tool
 * @param handle Agent 句柄
 * @param tool Tool 实例
 * @return 0 成功，负值失败
 */
int ai_register_tool(ai_handle_t *handle, const ai_tool_t *tool);

/**
 * @brief 获取 Agent 状态
 * @param handle Agent 句柄
 * @return 状态
 */
agent_state_t ai_get_state(ai_handle_t *handle);

/**
 * @brief 设置 LLM 后端
 * @param handle Agent 句柄
 * @param backend LLM 后端
 * @return 0 成功，负值失败
 */
int ai_set_backend(ai_handle_t *handle, llm_backend_t backend);

/**
 * @brief 清除对话上下文
 * @param handle Agent 句柄
 */
void ai_clear_context(ai_handle_t *handle);

/**
 * @brief 获取对话历史
 * @param handle Agent 句柄
 * @param messages 消息数组
 * @param max_count 最大数量
 * @return 实际数量
 */
int ai_get_history(ai_handle_t *handle, agent_message_t *messages, uint8_t max_count);

#endif /* AI_AGENT_H */

