/**
 * @file ui_manager.h
 * @brief UI 管理器接口
 *
 * LVGL 界面管理、页面导航、状态栏
 * 2026 OpenVela AI 硬件开发者大赛 - team329
 */

#ifndef UI_MANAGER_H
#define UI_MANAGER_H

#include <stdint.h>
#include <stdbool.h>

/* 页面 ID 定义 */
typedef enum {
    PAGE_HOME = 0,
    PAGE_APP_LIST,
    PAGE_HEALTH,
    PAGE_SPORTS,
    PAGE_WEATHER,
    PAGE_MUSIC,
    PAGE_SETTINGS,
    PAGE_NOTIFICATIONS,
    PAGE_FIND_DEVICE,
    PAGE_ALARMS,
    PAGE_BREATHING,
    PAGE_PHONE,
    PAGE_HEART_RATE,
    PAGE_STEPS,
    PAGE_BLOOD_OXYGEN,
    PAGE_SLEEP,
    PAGE_STRESS,
    PAGE_MAX
} page_id_t;

/* 页面状态 */
typedef struct {
    page_id_t id;
    bool visible;
    void *data;
} page_state_t;

/* UI 配置 */
typedef struct {
    uint16_t width;
    uint16_t height;
    uint8_t status_bar_height;
    uint8_t header_height;
    bool dark_theme;
} ui_config_t;

/* UI 句柄 */
typedef struct {
    ui_config_t config;
    page_state_t pages[PAGE_MAX];
    page_id_t current_page;
    bool initialized;
} ui_handle_t;

/**
 * @brief 初始化 UI
 * @param handle UI 句柄
 * @return 0 成功，负值失败
 */
int ui_init(ui_handle_t *handle);

/**
 * @brief 切换页面
 * @param handle UI 句柄
 * @param page_id 目标页面 ID
 * @return 0 成功，负值失败
 */
int ui_switch_page(ui_handle_t *handle, page_id_t page_id);

/**
 * @brief 返回上一页
 * @param handle UI 句柄
 * @return 0 成功，负值失败
 */
int ui_go_back(ui_handle_t *handle);

/**
 * @brief 更新状态栏
 * @param handle UI 句柄
 * @param time 时间字符串
 * @param battery 电池电量 (0-100)
 * @param bluetooth 蓝牙状态
 */
void ui_update_status_bar(ui_handle_t *handle, const char *time, uint8_t battery, bool bluetooth);

/**
 * @brief 刷新 UI
 * @param handle UI 句柄
 */
void ui_refresh(ui_handle_t *handle);

#endif /* UI_MANAGER_H */

/**
 * @file health_manager.h
 * @brief 健康监测管理器接口
 *
 * 心率、血氧、睡眠、压力监测
 * 2026 OpenVela AI 硬件开发者大赛 - team329
 */

#ifndef HEALTH_MANAGER_H
#define HEALTH_MANAGER_H

#include <stdint.h>
#include <stdbool.h>

/* 心率数据 */
typedef struct {
    uint32_t bpm;
    uint8_t quality;
    bool is_measuring;
} heart_rate_data_t;

/* 血氧数据 */
typedef struct {
    uint8_t spo2;
    uint8_t quality;
    bool is_measuring;
} blood_oxygen_data_t;

/* 睡眠数据 */
typedef struct {
    uint32_t duration_min;
    uint32_t deep_sleep_min;
    uint32_t light_sleep_min;
    uint32_t rem_sleep_min;
} sleep_data_t;

/* 压力数据 */
typedef struct {
    uint8_t level;
    const char *label;
} stress_data_t;

/* 健康句柄 */
typedef struct {
    heart_rate_data_t heart_rate;
    blood_oxygen_data_t blood_oxygen;
    sleep_data_t sleep;
    stress_data_t stress;
    bool initialized;
} health_handle_t;

/**
 * @brief 初始化健康监测
 * @param handle 健康句柄
 * @return 0 成功，负值失败
 */
int health_init(health_handle_t *handle);

/**
 * @brief 获取心率数据
 * @param handle 健康句柄
 * @param data 心率数据
 * @return 0 成功，负值失败
 */
int health_get_heart_rate(health_handle_t *handle, heart_rate_data_t *data);

/**
 * @brief 开始心率测量
 * @param handle 健康句柄
 * @return 0 成功，负值失败
 */
int health_start_heart_rate(health_handle_t *handle);

/**
 * @brief 获取血氧数据
 * @param handle 健康句柄
 * @param data 血氧数据
 * @return 0 成功，负值失败
 */
int health_get_blood_oxygen(health_handle_t *handle, blood_oxygen_data_t *data);

/**
 * @brief 获取睡眠数据
 * @param handle 健康句柄
 * @param data 睡眠数据
 * @return 0 成功，负值失败
 */
int health_get_sleep(health_handle_t *handle, sleep_data_t *data);

/**
 * @brief 获取压力数据
 * @param handle 健康句柄
 * @param data 压力数据
 * @return 0 成功，负值失败
 */
int health_get_stress(health_handle_t *handle, stress_data_t *data);

#endif /* HEALTH_MANAGER_H */

